let peerLibrary;
export function loadPeer(){if(globalThis.Peer)return Promise.resolve(globalThis.Peer);if(peerLibrary)return peerLibrary;peerLibrary=new Promise((resolve,reject)=>{const script=document.createElement('script');const timer=setTimeout(()=>{script.remove();peerLibrary=null;reject(Error('Не вдалося завантажити мережевий модуль. Перевір інтернет.'));},15000);script.src='https://cdn.jsdelivr.net/npm/peerjs@1.5.5/dist/peerjs.min.js';script.onload=()=>{clearTimeout(timer);resolve(globalThis.Peer)};script.onerror=()=>{clearTimeout(timer);peerLibrary=null;reject(Error('Мережевий модуль недоступний. Спробуй ще раз.'));};document.head.append(script);});return peerLibrary;}
export function profile(value){return {name:String(value?.name||'Гравець').replace(/[<>\u0000-\u001f]/g,'').slice(0,18),car:String(value?.car||'301').slice(0,30),color:/^#[0-9a-f]{6}$/i.test(value?.color)?value.color:'#aaba96'};}
export function validSnapshot(s){return s&&['x','y','z','yaw','speed','health'].every(k=>typeof s[k]==='number'&&Number.isFinite(s[k]))&&Math.abs(s.x)<=250&&Math.abs(s.z)<=250&&s.y>=-5&&s.y<30&&Math.abs(s.speed)<250&&s.health>=0&&s.health<=100;}
export class GameRoom{
 constructor(events={}){this.events=events;this.links=new Map();this.members=new Map();this.snapshots=new Map();this.peer=null;this.host=false;this.connected=false;this.round=null;this.generation=0;}
 emit(type,data){this.events[type]?.(data);}
 send(c,data){if(c?.open&&c.bufferSize<12)c.send(data);}
 broadcast(data){for(const c of this.links.values())this.send(c,data);}
 roster(){const list=[...this.members.entries()].map(([id,p])=>({id,...p}));this.broadcast({type:'roster',list});this.emit('roster',list);}
 async open(code,person){this.leave();const generation=this.generation;const Peer=await loadPeer();if(generation!==this.generation)return;this.host=!code;this.code=code||Array.from(crypto.getRandomValues(new Uint8Array(8)),n=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[n%'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'.length]).join('');this.me=profile(person);this.peer=new Peer(this.host?'gc18-'+this.code:undefined,{debug:0});const peer=this.peer;this.timer=setTimeout(()=>{if(!this.connected){this.emit('error','Час з’єднання вичерпано. Спробуй іншу мережу або створи кімнату ще раз.');this.leave();}},20000);
 peer.on('open',id=>{if(peer!==this.peer)return;this.id=id;if(this.host){this.connected=true;clearTimeout(this.timer);this.members.set(id,this.me);this.emit('ready',this.code);this.roster();}else{this.attach(peer.connect('gc18-'+this.code,{reliable:true,serialization:'json',metadata:{version:18,profile:this.me}}));}});
 peer.on('connection',c=>{if(!this.host){c.close();return;}if(c.metadata?.version!==18||this.members.size>=4||this.round){c.on('open',()=>{this.send(c,{type:'reject',message:this.round?'Заїзд уже триває. Приєднайся після повернення в кімнату.':'Кімната заповнена або версія гри відрізняється.'});setTimeout(()=>c.close(),300);});return;}this.members.set(c.peer,profile(c.metadata.profile));this.attach(c);});
 peer.on('error',error=>{if(peer!==this.peer)return;const messages={'peer-unavailable':'Кімнату не знайдено. Перевір код і чи відкрив її власник.','unavailable-id':'Цей код уже зайнятий. Створи нову кімнату.','network':'Не вдалося зв’язатися із сервером з’єднань.','webrtc':'Мережа не дозволяє пряме з’єднання. Спробуй іншу мережу.'};this.emit('error',messages[error.type]||'Помилка з’єднання. Спробуй приєднатися знову.');if(!this.connected)this.leave();});
 peer.on('disconnected',()=>{if(peer!==this.peer)return;if(this.connected)this.emit('error','Сервер з’єднань недоступний. Нові гравці тимчасово не можуть приєднатися.');});
 }
 attach(c){this.links.set(c.peer,c);const timeout=setTimeout(()=>{if(!c.open){c.close();this.links.delete(c.peer);this.members.delete(c.peer);if(this.host)this.roster();}},15000);c.on('open',()=>{clearTimeout(timeout);if(this.host)this.roster();});c.on('data',data=>{if(this.links.get(c.peer)!==c||!data||typeof data!=='object')return;
 if(data.type==='reject'&&!this.host){this.emit('error',String(data.message).slice(0,180));this.leave();return;}
 if(this.host){if(data.type==='profile'&&!this.round){this.members.set(c.peer,profile(data.profile));this.roster();}if(data.type==='state'&&this.round&&data.round===this.round.id&&validSnapshot(data.state)){const now=performance.now(),last=c.lastState||0;if(now-last<35)return;c.lastState=now;const {x,y,z,yaw,speed,health}=data.state;this.snapshots.set(c.peer,{x,y,z,yaw,speed,health,id:c.peer});}return;}
 if(data.type==='roster'&&Array.isArray(data.list)&&data.list.length<=4){this.members=new Map(data.list.filter(p=>typeof p.id==='string').map(p=>[p.id,profile(p)]));if(!this.connected){this.connected=true;clearTimeout(this.timer);this.emit('ready',this.code);}this.emit('roster',[...this.members].map(([id,p])=>({id,...p})));}
 if(data.type==='start'&&['free','crash'].includes(data.mode)&&typeof data.round==='string'&&Array.isArray(data.players)&&data.players.length<=4){this.round={id:data.round,mode:data.mode,players:data.players.filter(id=>this.members.has(id))};this.snapshots.clear();this.emit('start',this.round);}
 if(data.type==='states'&&data.round===this.round?.id&&Array.isArray(data.states)){this.snapshots.clear();for(const s of data.states.slice(0,4))if(this.members.has(s.id)&&validSnapshot(s))this.snapshots.set(s.id,s);this.emit('states',[...this.snapshots.values()]);}
 if(data.type==='lobby'){this.round=null;this.snapshots.clear();this.emit('lobby');}
 });c.on('close',()=>{clearTimeout(timeout);if(this.links.get(c.peer)!==c)return;this.links.delete(c.peer);this.members.delete(c.peer);this.snapshots.delete(c.peer);if(this.host)this.roster();else{this.emit('error','Власник закрив кімнату або з’єднання втрачено.');this.leave();}});c.on('error',()=>{this.emit('error','З’єднання з гравцем перервано.');c.close();});}
 updateProfile(p){this.me=profile(p);if(!this.connected)return;if(this.host){this.members.set(this.id,this.me);this.roster();}else this.send([...this.links.values()][0],{type:'profile',profile:this.me});}
 start(mode){if(!this.host||!this.connected||this.round||!['free','crash'].includes(mode))return false;this.round={id:crypto.randomUUID(),mode,players:[...this.members.keys()]};this.snapshots.clear();this.broadcast({type:'start',mode,round:this.round.id,players:this.round.players});this.emit('start',this.round);return true;}
 state(s){if(!this.round||!validSnapshot(s))return;this.snapshots.set(this.id,{...s,id:this.id});if(this.host){const states=[...this.snapshots.values()];this.broadcast({type:'states',round:this.round.id,states});this.emit('states',states);}else this.send([...this.links.values()][0],{type:'state',round:this.round.id,state:s});}
 lobby(){if(!this.host)return;this.round=null;this.snapshots.clear();this.broadcast({type:'lobby'});this.emit('lobby');}
 leave(){this.generation++;clearTimeout(this.timer);const peer=this.peer;this.peer=null;this.links.clear();this.members.clear();this.snapshots.clear();this.round=null;this.connected=false;peer?.destroy();this.emit('left');}
}
